    double min2 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMinC(box2, dim);
    double max2 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMaxC(box2, dim);

    if (max1 < min2 || max2 < min1) {
        return BoxRelation::Separated;
    }
    if (max1 == min2 || max2 == min1) {
        continue; // Adjacent in this dimension, check others
    }
}
// If we got here, boxes overlap in all dimensions
for (int dim = 0; dim < 3; ++dim) {
    double min1 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMinC(box1, dim);
    double max1 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMaxC(box1, dim);
    double min2 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMinC(box2, dim);
    double max2 = OrthoTree::UnrealAdaptor::UnrealAdaptorBasics3D<double, FVector3f, BoundingBox3D, FRay3f, FPlane3f>::GetBoxMaxC(box2, dim);

    if (max1 == min2 || max2 == min1) {
        return BoxRelation::Adjacent;
    }
}
return BoxRelation::Overlapped;

